// Groundbreak art components. Art: public/groundbreak, generated by scripts/groundbreak-art/build-icons.py and
// build-scene.py. The UI owns zoom, pan and input; these components only draw.
"use client";

import { useEffect, useRef, useState, type CSSProperties } from "react";
import { GB_ICONS, GB_ICON_CELL, GB_ICON_COLS, GB_ICON_ROWS, GB_ICON_SHEET, type GbIconId } from "./icons";
import { GB_BACKDROP, GB_JOBS, GB_JOB_ORDER, type GbJobId } from "./scene-data";
import "./art.css";

export { GB_ICONS, GB_JOBS, GB_JOB_ORDER, GB_BACKDROP };
export type { GbIconId, GbJobId };

/** One icon from the 64 px sheet, drawn crisp at any size (use multiples of 32 for the cleanest pixels). */
export function GbIcon({ id, size = 32, className, title }: { id: GbIconId; size?: number; className?: string; title?: string }) {
    const i = GB_ICONS[id];
    const k = size / GB_ICON_CELL;
    const style: CSSProperties = {
        width: size, height: size,
        backgroundImage: `url("${GB_ICON_SHEET}")`,
        backgroundSize: `${GB_ICON_COLS * GB_ICON_CELL * k}px ${GB_ICON_ROWS * GB_ICON_CELL * k}px`,
        backgroundPosition: `${-(i % GB_ICON_COLS) * size}px ${-Math.floor(i / GB_ICON_COLS) * size}px`,
    };
    return <span role={title ? "img" : undefined} aria-label={title} aria-hidden={title ? undefined : true}
        className={`gba-icon ${className ?? ""}`} style={style} />;
}

/** Frame index for a phase name, or a 0..1 progress through the job. */
export function jobFrame(job: GbJobId, at: string | number): number {
    const frames = GB_JOBS[job].frames as readonly string[];
    if (typeof at === "string") return Math.max(0, frames.indexOf(at));
    return Math.min(frames.length - 1, Math.max(0, Math.floor(at * (frames.length - 1) + 1e-6)));
}

/** One job frame (a cutaway building at one stage). Cross-fades when the frame changes. */
export function GbJob({ job, frame, scale = 1, style }: { job: GbJobId; frame: number; scale?: number; style?: CSSProperties }) {
    const j = GB_JOBS[job];
    const [prev, setPrev] = useState<number | null>(null);
    const last = useRef(frame);
    useEffect(() => {
        if (last.current === frame) return;
        setPrev(last.current);
        last.current = frame;
        const t = window.setTimeout(() => setPrev(null), 520);
        return () => window.clearTimeout(t);
    }, [frame]);
    const cell = (f: number, cls: string) => (
        <div className={cls} style={{
            backgroundImage: `url("${j.src}")`,
            backgroundSize: `${j.w * j.frames.length * scale}px ${j.h * scale}px`,
            backgroundPosition: `${-f * j.w * scale}px 0`,
        }} />
    );
    return (
        <div className="gba-job" style={{ width: j.w * scale, height: j.h * scale, ...style }} aria-label={`${j.name}: ${j.frames[frame]}`}>
            {prev !== null && cell(prev, "gba-job-f gba-out")}
            {cell(frame, `gba-job-f ${prev !== null ? "gba-in" : ""}`)}
        </div>
    );
}

const PARALLAX: Record<string, number> = { sky: 0.08, hills: 0.25, city: 0.45, bay: 0.6, shore: 1 };

/**
 * The full site view: SF Bay backdrop layers with parallax, the current job's cutaway on the near shore, and every
 * finished job standing beside it as the skyline you have built.
 *
 * Coordinates are native art pixels (backdrop is GB_BACKDROP.w x .h). `zoom` 1 fits the backdrop to the container
 * width; `focusX` / `focusY` (native px) is the point kept at the centre. The UI thread owns input and clamps.
 */
export function GbScene({ job, frame, city = 0, built = [], zoom = 1, focusX, focusY, lowFx = false, className }: {
    job: GbJobId; frame: number; city?: 0 | 1 | 2 | 3 | 4; built?: GbJobId[]; zoom?: number;
    focusX?: number; focusY?: number; lowFx?: boolean; className?: string;
}) {
    const B = GB_BACKDROP;
    const box = useRef<HTMLDivElement>(null);
    const [cw, setCw] = useState(1440);
    const [ch, setCh] = useState(600);
    useEffect(() => {
        const el = box.current;
        if (!el) return;
        const ro = new ResizeObserver(() => { setCw(el.clientWidth); setCh(el.clientHeight); });
        ro.observe(el);
        return () => ro.disconnect();
    }, []);
    const fit = Math.max(cw / B.w, ch / B.h);
    const s = fit * zoom;
    const fx = focusX ?? JOB_X + GB_JOBS[job].w / 2;
    const fy = focusY ?? B.siteY - 60;
    const layer = (name: string, src: string) => {
        const p = PARALLAX[name.startsWith("city") ? "city" : name];
        // layers further back move less with the focus point and scale up less with zoom
        const z = 1 + (zoom - 1) * p;
        const sc = fit * z;
        const tx = cw / 2 - (B.w / 2 + (fx - B.w / 2) * p) * sc;
        const ty = ch / 2 - (B.h / 2 + (fy - B.h / 2) * p) * sc;
        return <img key={name} src={src} alt="" draggable={false} className="gba-layer"
            style={{ width: B.w, height: B.h, transform: `translate(${tx}px, ${ty}px) scale(${sc})` }} />;
    };
    const tx = cw / 2 - fx * s;
    const ty = ch / 2 - fy * s;
    let x = JOB_X + GB_JOBS[job].w + 24;
    return (
        <div ref={box} className={`gba-scene ${lowFx ? "gba-lowfx" : ""} ${className ?? ""}`}>
            {layer("sky", B.layers.sky)}
            {layer("hills", B.layers.hills)}
            {layer(`city-${city}`, B.layers[`city-${city}`])}
            {layer("bay", B.layers.bay)}
            {layer("shore", B.layers.shore)}
            <div className="gba-near" style={{ transform: `translate(${tx}px, ${ty}px) scale(${s})` }}>
                {built.filter((b) => b !== job).map((b) => {
                    const j = GB_JOBS[b];
                    const el = <GbJob key={b} job={b} frame={j.frames.length - 1}
                        style={{ position: "absolute", left: x, top: B.siteY + j.ground - j.h }} />;
                    x += j.w - 40;
                    return el;
                })}
                <GbJob job={job} frame={frame} style={{ position: "absolute", left: JOB_X, top: B.siteY + GB_JOBS[job].ground - GB_JOBS[job].h }} />
                {!lowFx && <div className="gba-dust" style={{ left: JOB_X, top: B.siteY - 40, width: GB_JOBS[job].w }} />}
            </div>
        </div>
    );
}

/** Native x where the current job stands on the near shore (right of the port cranes). */
export const JOB_X = 560;
